def _runner(adb_runner_or_none):
    if adb_runner_or_none is None:
        return get_public_adb_cmd_runner()
    return adb_runner_or_none


def _parse_result_adb_forward_list(search_ue, result, target_ue_port=38300):
    forward_list = []
    # TODO: znajdz wszystkie wystapienia patternow
    for match in re.finditer(adb_forwarding_pattern, result):
        found_ue_sn = match.group(1)
        tcp_port = int(match.group(2))
        ue_tcp_port = int(match.group(3))
        if search_ue == found_ue_sn and ue_tcp_port == target_ue_port:
            logger.debug("found port forwarding: {} -> {}".format(ue_tcp_port, tcp_port), extra={'ue_id': search_ue})
            forward_list.append(tcp_port)
        else:
            logger.debug("found and ignore adb port to forwarding on ue: %s port : %d -> %d" % (found_ue_sn,
                                                                                                ue_tcp_port, tcp_port))
    return forward_list


def adb_forward_list(ue_sn, adb_runner=None):
    """
    List ports forwarded by adb to specified UE.
    :param adb_runner:
    :param ue_sn:
    :return: List(int)
    """
    adb_runner = _runner(adb_runner)
    result, _ = adb_runner.adb_read_adb_output(None, ['forward', '--list'])
    forward_list = _parse_result_adb_forward_list(ue_sn, result)
    logger.debug('ports forwarded by adb to specified ue: {}'.format(forward_list))
    return forward_list


def adb_is_screen_on(ue_sn):
    """
    Get screen state from ue
    :param ue_sn:
    :return:
    """
    result, _ = adb_run_cmd(ue_sn, "shell", ["dumpsys", "display", "|", "grep", "mScreenState"])
    if result.strip() == "mScreenState=ON":
        return True
    return False


def adb_push_file(ue_sn, path_to_local_file, path_to_ue_file, adb_runner=None, timeout=60):
    """
    Pushes a file to UE.
    :param ue_sn: ue's serial number
    :param path_to_local_file: path to file on uepc
    :param path_to_ue_file: path to file on ue
    :param adb_runner:
    :param timeout:
    :return: List(str)
    """
    return adb_action_push_file(ue_sn, path_to_local_file, path_to_ue_file, adb_runner, timeout)


def adb_pull_file(ue_sn, path_to_local_file, path_to_ue_file, adb_runner=None, timeout=60):
    """
    Pulles a file from UE.
    :param ue_sn: ue's serial number
    :param path_to_local_file: path to file on uepc
    :param path_to_ue_file: path to file on ue
    :param adb_runner:
    :param timeout:
    :return: List(str)
    """
    return adb_action_pull_file(ue_sn, path_to_local_file, path_to_ue_file, adb_runner, timeout)


def adb_action_pull_file(ue_sn, path_to_local_file, path_to_ue_file, adb_runner=None, timeout=60):
    """
    Pulles a file from UE.
    :param ue_sn: ue's serial number
    :param path_to_local_file: path to file on uepc
    :param path_to_ue_file: path to file on ue
    :param action: 'push' or 'pull'
    :param adb_runner:
    :param timeout:
    :return: List(str)
    """
    adb_runner = _runner(adb_runner)
    logger.info('Pulling file from UE {} to {}'.format(path_to_ue_file, path_to_local_file))
    start_time = time.time()
    result = False
    while time.time() < start_time + timeout and not result:
        try:
            result, err = adb_runner.adb_read_adb_output(ue_sn, ["pull", path_to_ue_file, path_to_local_file])
            time.sleep(5)
        except PullPushFileError:
            logger.debug(
                'Failed to pull {} from ue {} to {} on uepc.'.format(path_to_ue_file, ue_sn, path_to_local_file))
    return result


def adb_action_push_file(ue_sn, path_to_local_file, path_to_ue_file, adb_runner=None, timeout=60):
    """
    Pulles a file from UE.
    :param ue_sn: ue's serial number
    :param path_to_local_file: path to file on uepc
    :param path_to_ue_file: path to file on ue
    :param adb_runner:
    :param timeout:
    :return: List(str)
    """
    adb_runner = _runner(adb_runner)
    logger.info('Pushing file from UE {} to {}'.format(path_to_local_file, path_to_ue_file))
    start_time = time.time()
    result = False
    while time.time() < start_time + timeout and not result:
        try:
            result, err = adb_runner.adb_read_adb_output(ue_sn, ["push", path_to_local_file, path_to_ue_file])
            time.sleep(5)
        except PullPushFileError:
            logger.debug(
                'Failed to push local file {} to ue {} to ue local path {}.'.format(path_to_local_file, ue_sn, path_to_ue_file))
    return result


def adb_run_cmd(ue_sn, cmd, args=None):
    """
    Run cmd on UE via adb shell
    :param ue_sn: UE serial number
    :param cmd: shell command
    :param args: arguments for command
    :return: (result, err)
    """
    if args is None:
        args = list()
    if isinstance(args, str):
        args = [str]
    adb_runner = None
    adb_runner = _runner(adb_runner)
    cmds = [cmd] + args
    result, err = adb_runner.adb_read_adb_output(ue_sn, cmds)
    logger.debug('run adb command {} with result: {}'.format(cmds, result))
    return result, err


def adb_forward_port(ue_sn, local_port, android_port=38300, adb_runner=None):
    """Adb forward port."""
    adb_runner = _runner(adb_runner)
    logger.debug("want to do port forward to port %d with ue %s" % (local_port, ue_sn))
    out, err = adb_runner.adb_read_adb_output(ue_sn, "forward tcp:%d tcp:%d" % (local_port, android_port))
    logger.debug("with result: %s\n%s" % (out, err))
    # TODO: bardziej zaawansowenie sprawdzaj czy adb nie wywalil bledu i czy port jest faktycznie forwardowany
    if 'error: device' in err and 'not found' in err:
        warn_log = "device '%s' not found during forwarding, stderr = '%s', stdout = '%s'" % (ue_sn, err, out)
        logger.warning(warn_log)
        return False
    logger.debug("forwarded fine")
    return True


def _get_serial_number_from_line(line):
    if line.startswith('*') or line == '':
        return None
    splits = line.split()
    device = splits[0]
    if device == '':
        return None
    return device


def _parse_result_adb_devices(result):
    devices = list()
    for line in result.split('\n'):
        line = line.rstrip()
        device = _parse_result_adb_devices_line(line)
        if device:
            devices.append(device)
    return devices


def _parse_result_adb_devices_line(line):
    if line == 'List of devices attached':
        return
    device = _get_serial_number_from_line(line)
    if device:
        return device
    elif line == '* failed to start daemon *':
        raise UnexpectedCmdResultException("failed to start adb daemon, no devices found")


def adb_devices(adb_runner=None):
    """
    :param adb_runner:
    :return:
    """
    adb_runner = _runner(adb_runner)
    out, err = adb_runner.adb_read_adb_output(None, ["devices"])
    logger.debug("After adb devices there is output:\n%s\nerr:\n%s" % (out, err))
    return _parse_result_adb_devices(out)


