def adb_start_mobile_app(sn, adb_cmd_runner=None):
    """
    Starts mobile app on UE.
    :param adb_runner:
    :param sn: string
    :return: bool - if success
    """
    logger.info("Starting adb mobile app: " + str(sn))
    package_name = get_mobile_app_package_name(sn)
    start_app_cmds = _get_app_start_cmds(package_name)
    usb_service_name = _get_usb_service_name(package_name)
    logger.debug("Trying to run commands inside start mobile app.")
    results = _run_start_app_commands(sn, start_app_cmds)
    if _verify_app_start_response_succeed(results, package_name, is_raise_needed=False):
        adb_await_activity_service(sn, package_name, usb_service_name, wait_time=60, should_raise=True)
    else:
        logger.debug("Waiting 5s and trying second time to run command inside start mobile app.")
        time.sleep(5)
        results = _run_start_app_commands(sn, start_app_cmds)
        _verify_app_start_response_succeed(results, package_name, is_raise_needed=True)
    logger.debug("Starting mobile app via adb finished.")


def adb_restart_mobile_app(sn):
    logger.debug("Trying to restart mobile application")
    package_name = get_mobile_app_package_name(sn)
    logger.debug("Stopping app")
    adb_force_stop_package(sn, package_name)
    logger.debug("Starting app")
    adb_start_mobile_app(sn)


def _run_start_app_commands(sn, start_app_commands):
    results = []
    for cmd in start_app_commands:
        result = _run_app_command_with_retries(sn, cmd, retries=10)
        results.append(result)
    return ' '.join(results)


def _run_app_command_with_retries(sn, cmd, retries=5):
    accepted_error = 'Warning: Activity not started'
    for retry in range(retries):
        logger.debug("Adb starting mobile app shell command: {}, {} try".format(cmd, retry))
        result, err = adb_run_cmd(sn, "shell", [cmd])
        logger.debug(
            "Command: {} executed on ue: {}, \n"
            "result: {}, \nerror: {}".format(cmd, sn, result, err))
        if result and (not err or accepted_error in err):
            return result
    raise UnexpectedCmdResultException("Starting app command: {} failed.".format(cmd))


def _verify_app_start_response_succeed(results, package_name, is_raise_needed=False):
    """
    Checks if cmd outputs after app start is correct, if not raises exception.
    :return:
    """
    if "Starting: Intent {{ cmp={activity_name}".format(
            activity_name=NAA_ACTIVITY_PATH if package_name == NAA_PACKAGE_NAME else UEM_ACTIVITY_PATH) in results:
        return True
    if is_raise_needed:
        raise InvalidAppStartResponse(results)


def get_mobile_app_package_name(sn, timeout=60):
    """
    Gets package name of mobile application.
    :return:
    """
    adb_stdout, adb_stderr = "", ""
    end_wait_time = time.time() + timeout
    while time.time() < end_wait_time:
        adb_stdout, adb_stderr = adb_run_cmd(sn, 'shell', LIST_PACKAGES_GREP_NOKIA)
        if 'package:{}'.format(UEM_PACKAGE_NAME) in adb_stdout:
            return UEM_PACKAGE_NAME
        if 'package:{}'.format(NAA_PACKAGE_NAME) in adb_stdout:
            return NAA_PACKAGE_NAME
        time.sleep(2)
    error_message = 'Unable to determine which ue control apk is installed.\nstdout: {}\nstderr: {}'.format(
        adb_stdout, adb_stderr)
    raise UnknownUeControlApkException(error_message)


def _get_usb_service_name(package_name):
    if package_name == NAA_PACKAGE_NAME:
        return NAA_USB_SERVICE
    if package_name == UEM_PACKAGE_NAME:
        return UEM_USB_SERVICE
    raise InvalidAppError('{} is not a valid supported application.'.format(package_name))


def _get_app_start_cmds(package_name):
    if package_name == NAA_PACKAGE_NAME:
        return START_NAA_CMDS
    if package_name == UEM_PACKAGE_NAME:
        return START_UEM_CMDS
    raise InvalidAppError('{} is not a valid supported application.'.format(package_name))


def adb_reboot(sn, wait_ue_disappear=True, adb_runner=None):
    """
    Reboots UE
    :param sn:
    :param wait_ue_disappear:
    :param adb_runner:
    :return:
    """
    adb_runner = _runner(adb_runner)
    if sn is not None and sn not in adb_devices(adb_runner):
        raise UeSerialNumberUnavailableException(sn)

    adb_runner.adb_read_adb_output(sn, ["reboot"])

    if wait_ue_disappear:
        start_wait_time = time.time()
        end_wait_time = time.time() + 120
        while time.time() < end_wait_time:
            if sn not in adb_devices(adb_runner):
                logger.info("UE %s disappear after %.2f seconds after reboot" % (sn, time.time() - start_wait_time))
                return True
            time.sleep(0.1)
        raise UeNotDisappearAfterReboot(sn, time.time() - start_wait_time)
    return True


def adb_reboot_and_wait_ue_appear(sn, wait_time=75, adb_runner=None):
    """
    Reboots UE and waits until UE will appear.
    :param sn:
    :param adb_runner:
    :return:
    """
    wait_time = int(wait_time)
    logger.info('Rebooting UE via adb, sn: {}, wait time is: {}'.format(sn, wait_time))
    adb_reboot(sn, adb_runner)
    adb_await_for_ue(sn, wait_time, adb_runner)


def adb_is_ue_available(ue_sn, time_frame=None, adb_runner=None):
    """
    Is UE serial number visible at adb devices.
    It check if UE stays in adb devices for a specified time_frame if specified
    :param ue_sn: UE serial number
    :param time_frame: a time period (s) in which we expect the UE weill be available in adb devices
    :param adb_runner: AdbRunner
    :return:
    """
    if not time_frame:
        return ue_sn in adb_devices(adb_runner)
    end_time = time.time() + time_frame
    while time.time() < end_time:
        logger.debug("Checking if UE is available for a specified time_frame")
        if ue_sn not in adb_devices(adb_runner):
            logger.debug("UE {} disappeared from adb devices".format(ue_sn))
            return False
        time.sleep(1)
    return True


def adb_await_for_ue(ue_sn, wait_time=75, adb_runner=None):
    """
    Waits until UE will appear in adb devices
    :return:
    """
    end_wait_time = time.time() + wait_time
    while time.time() < end_wait_time:
        time.sleep(2)
        logger.debug("Awaiting for {} UE. {} seconds left.".format(ue_sn, end_wait_time - time.time()))
        if ue_sn in adb_devices(adb_runner):
            logger.info('UE: {} available in adb devices'.format(ue_sn))
            return True
    raise UeSerialNumberUnavailableException(ue_sn)


def adb_await_boot_complete(ue_sn, wait_time=60):
    """
    Waits until UE will appear in adb devices
    :return:
    """
    start_wait_time = time.time()
    end_wait_time = time.time() + wait_time
    while time.time() < end_wait_time:
        result, err = adb_run_cmd(ue_sn, "shell", ["getprop", "dev.bootcomplete"])
        if "1" in result:
            return True
        if err:
            logger.error("adb_await_boot_complete error: {}".format(err))
        time.sleep(2)
    raise UeBootTimeout(ue_sn, time.time() - start_wait_time)


def adb_await_activity_service(ue_sn, package_name, activity_service_name, wait_time=60, should_raise=True):
    """
    Awaits for a specified activity service
    :param ue_sn: Ue serial number
    :param activity_service_name: activity service string to look for
    :param wait_time: time to wait in seconds
    :param should_raise: whether it should raise if activity not appeared in specified wait_time
    :return:
    """
    end_wait_time = time.time() + wait_time
    while time.time() < end_wait_time:
        result, err = adb_run_cmd(ue_sn, "shell", ["dumpsys", "activity", "services", "{}".format(package_name)])
        if activity_service_name in result:
            return True
        if err:
            logger.error("adb_is_activity_service_running error: {}".format(err))
        time.sleep(1)
    if should_raise:
        raise UeActivityServiceNotRunning(ue_sn, activity_service_name, wait_time)


def adb_start_activity(ue_sn, package_name, activity_name):
    """
    Starts activity on package
    :param ue_sn: UE serial number
    :param package_name: apk package name
    :param activity_name: Name of the activity to be started
    :return:
    """
    result, err = adb_run_cmd(ue_sn, "shell", ["am", "start", "-n", "{}/.{}".format(package_name, activity_name)])
    if result:
        return True
    if err:
        logger.error("adb_is_activity_service_running error: {}".format(err))
    return False


def adb_send_key_code(ue_sn, key, keyevent='keyevent'):
    """
    Wake device screen by sending an input keyevent via adb shell. Sending POWER key by default
    :param ue_sn: UE serial number to be waked up
    :param key: key to be pressed to wake device up
    :param keyevent: parameter for adb shell input, in most cases it should be keyevent.
    :return:
    """
    # TODO: może warto domyślnie użyć KEYCODE_WAKEUP zamiast KEYCODE_POWER skoro zależy nam tylko na pobudzeniu ekranu
    #  a nie jego wygaszeniu?
    result, err = adb_run_cmd(ue_sn, "shell", ["input ", keyevent, key])
    if result:
        logger.error("adb_wake_device ok: {}".format(result))
        return True
    if err:
        logger.error("adb_wake_device error: {}".format(err))
        if 'Error: Unknown command: keyevent' in err:
            logger.debug("adb_send_key_code via adb shell input keyevent failed. Retrying with adb shell input keyboard.")
            return adb_send_key_code(ue_sn, key, keyevent='keyboard')
    return False


def adb_send_tap(ue_sn, x, y):
    """
    Simulate physical finger-tap by sending an input tap via adb shell.
    :param ue_sn: UE serial number to be waked up
    :param x: parameter for adb shell input tap - x coordinate on the screen.
    :param y: parameter for adb shell input tap - y coordinate on the screen.
    :return:
    """
    coord_x = x if isinstance(x, int) else int(x)
    coord_y = y if isinstance(y, int) else int(y)

    if coord_x < 0:
        raise Exception("Error: {} value is not valid tap.X coordinate.".format(x))
    if coord_y < 0:
        raise Exception("Error: {} value is not valid tap.Y coordinate.".format(y))

    _, err = adb_run_cmd(ue_sn, "shell", ["input ", 'tap', str(coord_x), str(coord_y)])
    if err:
        logger.error("adb shell input tap error: {}".format(err))
        return False
    return True


def adb_force_stop_package(ue_sn, package_name):
    """
    Completely stop the given application package.
    :param ue_sn: UE serial number
    :param package_name: package to stop
    :return:
    """
    result, err = adb_run_cmd(ue_sn, "shell", ["am ", "force-stop", package_name])
    if result:
        logger.error("adb_force_stop_package ok: {}".format(result))
        return True
    if err:
        logger.error("adb_force_stop_package error: {}".format(err))
    return False


def adb_get_device_timestamp(ue_sn):
    """
    Get device timestamp and return output or error of adb shell date command
    :param ue_sn: UE serial number
    :return:
    """
    result, err = adb_run_cmd(ue_sn, "shell", ["date"])
    if result:
        result = result.splitlines()[0]
        logger.error("adb_get_device_time ok: {}".format(result))
        return result
    if err:
        logger.error("adb_get_device_time error: {}".format(err))
    return err


