def adb_start_activity_settings(ue_sn, setting_cmd, clear_task=False):
    setting = setting_cmd
    if clear_task:
        setting += ' --activity-clear-task'
    out, err = adb_run_cmd(ue_sn, 'shell', [setting])
    if err:
        raise Exception("Error: {} occurred when running command with adb: {}".format(err, setting))
    return out


def adb_cat_view_layout_xml(ue_sn, timeout=15):
    for i in range(3):
        logger.debug("Trying to get layout of phone desktop, ue_sn: {}, {} try.".format(ue_sn, i))
        adb_wake_up_screen(ue_sn)
        start_time = time.time()
        while time.time() < start_time + timeout:
            out, err = adb_run_cmd(ue_sn, 'shell', [AdbShellCommands.CAT_VIEW_LAYOUT_XML])

            no_error = out and not err
            no_interrupting_error = out and XIAOMI_NON_BLOCKING_ERROR in err
            if no_error or no_interrupting_error:
                return out, err
    raise Exception('Cannot get leyout of phone desktop, ue_sn: {}, 3 retries failed'.format(ue_sn))


