def _add_cmd_prefix(cmd, prefix):
    return "{} {}".format(prefix, cmd) if prefix else cmd


def adb_get_location_providers_state(ue_sn, su_prefix):
    cmd_location_get_providers_state = _add_cmd_prefix(AdbShellCommands.LOCATION_GET_PROVIDERS_STATE, su_prefix)
    stdout_location_providers_state, _ = adb_run_cmd(ue_sn, 'shell', [cmd_location_get_providers_state])
    return stdout_location_providers_state


def adb_get_location_mode_state(ue_sn, su_prefix):
    cmd_location_get_mode_state = _add_cmd_prefix(AdbShellCommands.LOCATION_GET_MODE_STATE, su_prefix)
    stdout_location_mode_state, _ = adb_run_cmd(ue_sn, 'shell', [cmd_location_get_mode_state])
    return stdout_location_mode_state


def adb_set_location_providers(ue_sn, su_prefix, providers_list=None):
    """
    Should work for enabling location services with android 9 and below
    :param ue_sn:
    :param su_prefix:
    :param providers_list: ['gps'] -> device only, ['network'] -> battery saving, ['gps', 'network'] -> high accuracy
    """
    if providers_list is None:
        providers_list = ['gps', 'network']

    set_location_providers_cmd_list = \
        [_add_cmd_prefix(AdbShellCommands.LOCATION_SET_PROVIDERS + prov, su_prefix) for prov in providers_list]

    for cmd in set_location_providers_cmd_list:
        adb_run_cmd(ue_sn, 'shell', [cmd])


def adb_set_location_mode(ue_sn, su_prefix, mode=3):
    """
    Should work for enabling location services with android 10 and above
    :param ue_sn:
    :param su_prefix:
    :param mode: 0 -> location services disabled, 1 -> ?, 2 -> ?, 3 -> high accuracy
    """
    if mode not in [0, 1, 2, 3]:
        raise Exception(
            "Unrecognised argument: {}. Mode should should be in [0, 1, 2, 3]".format(mode))

    set_location_mode_cmd = _add_cmd_prefix(AdbShellCommands.LOCATION_SET_MODE + str(mode), su_prefix)

    adb_run_cmd(ue_sn, 'shell', [set_location_mode_cmd])


